import os
import ast

for root, _, files in os.walk("app"):
    for file in files:
        if file.endswith(".py") and file != "auth.py":
            path = os.path.join(root, file)
            with open(path, "r", encoding="utf-8") as f:
                code = f.read()
            if "legacy_auth" in code:
                print("=" * 60)
                print(f"FILE: {path}")
                print("=" * 60)
                tree = ast.parse(code)
                for node in ast.walk(tree):
                    if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):
                        # Check if legacy_auth is in this function
                        func_code = ast.unparse(node)
                        if "legacy_auth" in func_code:
                            print(func_code)
                            print("-" * 40)

