import os
import re
import difflib

# Let's list files to migrate
FILES_TO_MIGRATE = []

for root, _, files in os.walk("app"):
    for file in files:
        if file.endswith(".py") and file != "auth.py":
            path = os.path.join(root, file)
            with open(path, "r", encoding="utf-8") as f:
                code = f.read()
            if "legacy_auth" in code:
                FILES_TO_MIGRATE.append(path)

print(f"Found {len(FILES_TO_MIGRATE)} files to migrate.")

def migrate_file(filepath, write=False):
    with open(filepath, "r", encoding="utf-8") as f:
        content = f.read()

    lines = content.splitlines()
    new_lines = []

    current_func_scope = "read" # default
    in_function = False

    # Let's build a regex for legacy_auth calls
    legacy_auth_re = re.compile(r'legacy_auth\((user_id(_\d+)?)\)')

    for line in lines:
        if line.startswith("def handle_"):
            in_function = True
            # Determine scope for this function
            if "payload" in line:
                current_func_scope = "write"
            else:
                current_func_scope = "read"
            new_lines.append(line)
        elif line.startswith("from app.auth import legacy_auth"):
            new_lines.append("from app.auth import new_auth")
        else:
            if in_function:
                # Replace legacy_auth inside function with the correct scope
                line_modified = legacy_auth_re.sub(rf'new_auth(\1, scope="{current_func_scope}")', line)
                new_lines.append(line_modified)
            else:
                new_lines.append(line)

    new_content = "\n".join(new_lines) + "\n"

    if content != new_content:
        if write:
            with open(filepath, "w", encoding="utf-8") as f:
                f.write(new_content)
            print(f"Wrote changes to {filepath}")
    else:
        print(f"No changes for {filepath}")

# Let's apply on all files
for fp in FILES_TO_MIGRATE:
    migrate_file(fp, write=True)
